"""Shared mapping for distributor reports: product name -> one of Bobur's 14 products, region text -> 14 regions."""
import re

PRODUCTS = ['Риномакс Актив Таб №10', 'Риномакс Хот Лимон 22г №15 ', 'Риномакс Хот Эффект Лимон 22г №15',
            'Риномакс Хот.Экстра пор.22г.№15 Лимон', 'Риноксил Формула + 0,05% спрей 10мл',
            'Риноксил Кидс 0,025% 10 мл спрей', 'Риноксил Кидс капли 0.25%.10мл', 'Риноксил Бэби 0,01% 10 мл капли',
            'Риноксил 0,1% 10мл спрей', 'Форсил со вкусом апельсина 3г №30', 'Мирамистин 50мл р-р',
            'Тивомакс-Дарница 42мг/мл 100мл', 'Триомакс-Дарница 25мг/4мл №10', 'Эрегра 100мг №4']
REGIONS = ['Андижан', 'Бухара', 'Джизак', 'Каракалпакстан', 'Кашкадарья', 'Наваи', 'Наманган', 'Самарканд',
           'Сурхандарья', 'Сырдарья', 'Ташкент', 'Фергана', 'Ташкентская', 'Хорезм']
LAT = str.maketrans({'a': 'а', 'e': 'е', 'o': 'о', 'p': 'р', 'c': 'с', 'x': 'х', 'k': 'к', 'm': 'м', 't': 'т', 'h': 'н', 'b': 'в', 'y': 'у'})


def product(name) -> str | None:
    s = str(name).lower().translate(LAT).replace('ё', 'е')
    if 'риномакс' in s or 'rinomaks' in str(name).lower():
        if 'актив' in s:
            return PRODUCTS[0]
        if 'эффект' in s or 'еффект' in s or 'effekt' in str(name).lower():
            return PRODUCTS[2]
        if 'экстра' in s or 'екстра' in s or 'ekstra' in str(name).lower():
            return PRODUCTS[3]
        if 'хот' in s or 'xot' in str(name).lower() or 'hot' in str(name).lower():
            return PRODUCTS[1]
        return None
    if 'риноксил' in s:
        if 'формул' in s:
            return PRODUCTS[4]
        if 'кидс' in s or 'kids' in s:
            return PRODUCTS[6] if 'капл' in s else PRODUCTS[5]
        if 'беби' in s or 'бэби' in s or 'baby' in s:
            return PRODUCTS[7]
        if '0,1' in s or '0.1' in s:
            return PRODUCTS[8]
        return None
    if 'форсил' in s and '400' not in s and 'капс' not in s:
        return PRODUCTS[9]
    if 'мирамистин' in s:
        return PRODUCTS[10]
    if 'тивомакс' in s:
        return PRODUCTS[11]
    if 'триомакс' in s:
        return PRODUCTS[12]
    if 'эрегра' in s or 'ерегра' in s:
        return PRODUCTS[13]
    return None


RULES = [('андижан', 'Андижан'), ('бухар', 'Бухара'), ('бухор', 'Бухара'), ('джиз', 'Джизак'), ('жиз', 'Джизак'),
         ('каракалп', 'Каракалпакстан'), ('қорақалп', 'Каракалпакстан'), ('нукус', 'Каракалпакстан'),
         ('кашкадар', 'Кашкадарья'), ('қашқадар', 'Кашкадарья'), ('карши', 'Кашкадарья'), ('қарши', 'Кашкадарья'),
         ('навои', 'Наваи'), ('наваи', 'Наваи'), ('навоий', 'Наваи'), ('наманган', 'Наманган'),
         ('самарканд', 'Самарканд'), ('самарқанд', 'Самарканд'), ('сурхан', 'Сурхандарья'), ('сурхон', 'Сурхандарья'),
         ('термез', 'Сурхандарья'), ('термиз', 'Сурхандарья'), ('сырдар', 'Сырдарья'), ('сирдар', 'Сырдарья'),
         ('гулистан', 'Сырдарья'), ('фергана', 'Фергана'), ('фарғона', 'Фергана'), ('фаргона', 'Фергана'),
         ('коканд', 'Фергана'), ('хорезм', 'Хорезм'), ('хоразм', 'Хорезм'), ('ургенч', 'Хорезм'), ('урганч', 'Хорезм'),
         ('ташкентская', 'Ташкентская'), ('тошкент вил', 'Ташкентская'), ('ташкент обл', 'Ташкентская'),
         ('т.обл', 'Ташкентская'), ('чо.таш', 'Ташкентская'), ('ташкент', 'Ташкент'), ('тошкент', 'Ташкент')]


def region(text) -> str | None:
    s = str(text).lower().translate(LAT)
    if not s.strip() or s == 'nan':
        return None
    for k, v in RULES:
        if k in s:
            return v
    return None
